# Ajuste registros: los registros definitivos (spec `ajuste-registros`, §2.3). Todas sus listas son comunes
# (`fijos.LISTAS_COMUNES`); no hay listas propias.
LISTAS = ()


def _lista(lista, maxima=1, minima=1, otra=True, propias=(), **extra):
    return {'fuente': 'LISTA', 'lista': lista, 'minima': minima, 'maxima': maxima, 'otra': otra,
            'propias': propias, **extra}


def _referencia(referencia, maxima=1, minima=1, propias=(), **extra):
    return {'fuente': 'REFERENCIA', 'referencia': referencia, 'minima': minima, 'maxima': maxima,
            'propias': propias, **extra}


def _propias(*propias, **extra):
    return {'fuente': 'PROPIAS', 'minima': 1, 'maxima': 1, 'propias': propias, **extra}


def _piezas(fuente, propias=(), **extra):
    """Ajuste registros llm (lote 2): una pieza de la lista armada (§4), que resuelve `contexto.py` por cuenta."""
    return {'fuente': fuente, 'minima': 1, 'maxima': 1, 'otra': True, 'propias': propias, **extra}


def _podio(lista, otra=False):
    """Tres opciones ordenadas. Con «otra», se puede agregar más de una (`OTRA-1`…), cada una en su puesto."""
    return {'fuente': 'LISTA', 'lista': lista, 'minima': 3, 'maxima': 3, 'ordenada': True, 'otra': otra}


def _op(codigo, texto, **campos):
    """Opción propia: `pregunta` y `arranque` reemplazan los del ítem; `sin_llm`, no se evalúa con el LLM. Su tarjeta
    propia, si tiene, está en `datos/tarjetas_registros` (`por_opcion`)."""
    return {'codigo': codigo, 'texto': texto, **campos}


def _c(texto, **partes):
    """La consigna del ítem (§1): pregunta del texto (T) y, si las tiene, `dialogo` (D), `pregunta_eleccion` (E),
    `arranque` (⌨) y los ecos (`ecos_mostrar`, `ecos_llm`)."""
    return {'pregunta_texto': texto, **partes}


def _eco(origen, codigo, nombre=None, forma=None):
    """Un eco: TEXTO o ELECCION de un ítem anterior de la misma actividad, o REFERENCIA de la actividad. `forma` dice
    qué parte se toma (`primera`, `carrera`…); la redacción la hace `contexto.py`."""
    return {'origen': origen, 'codigo': codigo, **({'nombre': nombre} if nombre else {}),
            **({'forma': forma} if forma else {})}


